mapper.sql:
AND (
    o.security_level = 'GENERAL'
    OR #{allConfidential} = TRUE
    OR EXISTS (
        SELECT 1
        FROM opportunity_view_permissions ovp
        WHERE ovp.opportunity_id = o.opportunity_id
          AND ovp.user_id = #{userId}
    )
)

mapper.delete:
-- 보안 프로젝트 열람 허용 사용자를 전체 삭제한다.
DELETE FROM opportunity_view_permissions
WHERE opportunity_id = #{opportunityId}

-- 영업 사이트와 하위 진행 기록, 첨부파일 메타데이터, 열람 권한, 임원 코멘트를 삭제한다.
DELETE FROM opportunities
WHERE opportunity_id = #{opportunityId}

mapper.select:
-- 영업 사이트 목록을 검색 조건에 따라 조회한다. SELECT o.opportunity_id, o.sales_year, d.code AS department_code, d.name AS department_name, COALESCE(c.name, o.customer_name) AS customer_name, o.project_name, o.security_level, o.expected_order_period, o.expected_delivery_period, o.project_amount, o.owner_name, o.status, ps.probability, ps.name AS probability_stage_name FROM opportunities o INNER JOIN departments d ON d.department_id = o.department_id INNER JOIN probability_stages ps ON ps.probability_stage_id = o.probability_stage_id LEFT JOIN customers c ON c.customer_id = o.customer_id
AND o.sales_year = #{businessYear}
AND d.code = #{departmentCode}
AND o.status = #{status}
ORDER BY o.expected_order_year ASC NULLS LAST, o.expected_order_month ASC NULLS LAST, o.created_at DESC, o.opportunity_id DESC
ORDER BY o.expected_delivery_year ASC NULLS LAST, o.expected_delivery_quarter ASC NULLS LAST, o.created_at DESC, o.opportunity_id DESC
ORDER BY o.created_at DESC, o.opportunity_id DESC

-- 영업 사이트에 속한 진행 기록 여부를 검증한다.
SELECT
    COUNT(1)
FROM opportunity_progress op
WHERE op.opportunity_id = #{opportunityId}
  AND op.opportunity_progress_id = #{opportunityProgressId}
